From 0ad3e20ceb4043287731539cb55cb0d8e14cbcba Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 03:01:39 +0100
Subject: [PATCH] wizard: only warn about the adapter used for discovery

The pairing page warned that the adapter was not pairable whenever any
adapter was off or unpairable, and Make Pairable powered all of them on.
Now it only checks and fixes the adapter it actually discovers with.

BUG: 489394
---
 src/wizard/pages/discover.cpp | 14 ++++++--------
 1 file changed, 6 insertions(+), 8 deletions(-)

diff --git a/src/wizard/pages/discover.cpp b/src/wizard/pages/discover.cpp
index 8f3786e7..b78285ca 100644
--- a/src/wizard/pages/discover.cpp
+++ b/src/wizard/pages/discover.cpp
@@ -352,14 +352,7 @@ void DiscoverPage::usableAdapterChanged(BluezQt::AdapterPtr adapter)

 void DiscoverPage::checkAdapters()
 {
-    bool error = false;
-
-    Q_FOREACH (BluezQt::AdapterPtr adapter, m_manager->adapters()) {
-        if (!adapter->isPowered() || !adapter->isPairable()) {
-            error = true;
-            break;
-        }
-    }
+    const bool error = m_adapter ? !m_adapter->isPairable() : !m_manager->adapters().isEmpty();

     delete m_warningWidget;
     m_warningWidget = nullptr;
@@ -390,6 +383,11 @@ void DiscoverPage::fixAdaptersError()
 {
     m_manager->setBluetoothBlocked(false);

+    if (m_adapter) {
+        m_adapter->setPairable(true);
+        return;
+    }
+
     Q_FOREACH (BluezQt::AdapterPtr adapter, m_manager->adapters()) {
         adapter->setPowered(true);
         adapter->setPairable(true);
-- 
